import type { Page } from '@playwright/test';
import { test, expect } from '../../playwright';

// The response-pane actions (Copy, Download, Clear, Change Layout) only render once a response is
// present in the pane. `RequestExecutor` calls `fetch(resolvedUrl)` directly, so a send is made
// hermetic by mocking the sample collection's `get users` resolved URL (`{{host}}/api/users?…`,
// host = http://localhost:8081 in the Local env) rather than a proxy.
const USERS_BODY = '{"data":[{"id":1,"name":"Alice"}]}';

// Read and parse the clipboard, returning null while it is still empty/unparseable so `expect.poll`
// can retry until the async copy lands.
const readClipboardJson = (page: Page): Promise<unknown> =>
  page.evaluate(async () => {
    try {
      return JSON.parse(await navigator.clipboard.readText());
    } catch {
      return null;
    }
  });

// At the default (narrow) playground width the actions collapse into a kebab menu; each action is a
// menu item.
test.describe('response pane actions — collapsed', () => {
  test.use({ viewport: { width: 1280, height: 900 } });

  test.beforeEach(async ({ page, playground, responsePane }) => {
    await responsePane.mockUsersResponse(USERS_BODY);
    await page.goto('/#/?pg=1&dock=bottom');
    await playground.openSidebarItem('get users');
    await responsePane.send();
    // The actions only mount after the response lands.
    await expect(responsePane.actions).toBeVisible();
  });

  test('collapses into a kebab menu exposing Copy, Download, Clear and Change Layout', async ({
    responsePane
  }) => {
    await expect(responsePane.actionsMenuTrigger).toBeVisible();

    await responsePane.openActionsMenu();
    await expect(responsePane.copyMenuItem).toBeVisible();
    await expect(responsePane.downloadMenuItem).toBeVisible();
    await expect(responsePane.clearMenuItem).toBeVisible();
    await expect(responsePane.layoutMenuItem).toBeVisible();

    // Copy is clickable and the pane stays in its response state (no crash / no empty state).
    await responsePane.copyMenuItem.click();
    await expect(responsePane.actions).toBeVisible();
  });

  test('Copy writes the response body to the clipboard', async ({ page, responsePane }) => {
    await page.context().grantPermissions(['clipboard-read', 'clipboard-write']);

    await responsePane.openActionsMenu();
    await responsePane.copyMenuItem.click();

    // The copied text is pretty-printed JSON, so compare the parsed value rather than the raw string.
    await expect.poll(() => readClipboardJson(page)).toEqual(JSON.parse(USERS_BODY));
  });

  test('Clear returns the pane to the empty "Click Send" state', async ({ responsePane }) => {
    await responsePane.openActionsMenu();
    await responsePane.clearMenuItem.click();

    await expect(responsePane.emptyHint).toBeVisible();
    // The status-bar actions are gone once the response is cleared.
    await expect(responsePane.actions).toHaveCount(0);
  });

  test('Download triggers a browser download of the response', async ({ page, responsePane }) => {
    const downloadPromise = page.waitForEvent('download');
    await responsePane.openActionsMenu();
    await responsePane.downloadMenuItem.click();
    const download = await downloadPromise;
    // JSON body with no Content-Disposition and a `/api/users` path → the content-type extension.
    expect(download.suggestedFilename()).toBe('response.json');
  });
});

// When the response pane is wide enough, the actions expand from the kebab into inline buttons. At
// this width the pane stays wide in both orientations, so the inline Change-Layout button persists.
test.describe('response pane actions — expanded', () => {
  test.use({ viewport: { width: 1920, height: 900 } });

  test.beforeEach(async ({ page, playground, responsePane }) => {
    await responsePane.mockUsersResponse(USERS_BODY);
    await page.goto('/#/?pg=1');
    await playground.openSidebarItem('get users');
    await responsePane.send();
    await expect(responsePane.actions).toBeVisible();
  });

  test('shows the actions as inline buttons instead of the kebab menu', async ({ responsePane }) => {
    await expect(responsePane.inlineButtons).toBeVisible();
    await expect(responsePane.actionsMenuTrigger).toBeHidden();
    await expect(responsePane.inlineCopyButton).toBeVisible();
  });

  test('Copy writes the response body to the clipboard from the inline button', async ({
    page,
    responsePane
  }) => {
    await page.context().grantPermissions(['clipboard-read', 'clipboard-write']);

    await responsePane.inlineCopyButton.click();

    await expect.poll(() => readClipboardJson(page)).toEqual(JSON.parse(USERS_BODY));
  });

  test('Download triggers a browser download from the inline button', async ({ page, responsePane }) => {
    const downloadPromise = page.waitForEvent('download');
    await responsePane.inlineDownloadButton.click();
    const download = await downloadPromise;
    expect(download.suggestedFilename()).toBe('response.json');
  });

  test('Clear returns the pane to the empty state from the inline button', async ({ responsePane }) => {
    await responsePane.inlineClearButton.click();

    await expect(responsePane.emptyHint).toBeVisible();
    await expect(responsePane.actions).toHaveCount(0);
  });

  test('Change Layout toggles the container orientation horizontal <-> vertical', async ({
    playground,
    responsePane
  }) => {
    await expect(playground.divider).toHaveAttribute('data-orientation', 'horizontal');

    await responsePane.inlineChangeLayoutButton.click();
    await expect(playground.divider).toHaveAttribute('data-orientation', 'vertical');

    await responsePane.inlineChangeLayoutButton.click();
    await expect(playground.divider).toHaveAttribute('data-orientation', 'horizontal');
  });
});

// A response over the 10MB threshold swaps the body for the Large Response Warning banner, which
// carries its own View / Copy / Download controls. An ~11MB JSON string trips the threshold.
const LARGE_BODY = `{"blob":"${'x'.repeat(11 * 1024 * 1024)}"}`;

test.describe('large response warning actions', () => {
  test.use({ viewport: { width: 1280, height: 900 } });

  test('shows the banner with View, Copy and Download controls', async ({
    page,
    playground,
    responsePane
  }) => {
    await responsePane.mockUsersResponse(LARGE_BODY);
    await page.goto('/#/?pg=1&dock=bottom');
    await playground.openSidebarItem('get users');
    await responsePane.send();

    await expect(responsePane.largeResponseWarning).toBeVisible();
    await expect(responsePane.largeResponseView).toBeVisible();
    await expect(responsePane.largeResponseCopy).toBeVisible();
    await expect(responsePane.largeResponseDownload).toBeVisible();
    await expect(responsePane.largeResponseDownload).toBeEnabled();

    // Copy and Download are clickable without dismissing the banner.
    await responsePane.largeResponseCopy.click();
    await expect(responsePane.largeResponseWarning).toBeVisible();
  });
});

import { describe, it, expect } from 'vitest';
import { buildDigestAuthorization, findDigestChallenge, getDigestCredentials, parseChallenges } from './digest-auth';

const RFC_CHALLENGE = {
  realm: 'testrealm@host.com',
  qop: 'auth,auth-int',
  nonce: 'dcd98b7102dd2f0e8b11d0f600bfb0c093',
  opaque: '5ccc069c403ebaf9f0171e9517f40e41'
};

describe('parseChallenges', () => {
  it('parses a quoted challenge with qop list and unquoted algorithm', () => {
    const header = 'Digest realm="digest-lab", nonce="abc123", opaque="deadbeef", algorithm=MD5, qop="auth"';
    expect(parseChallenges(header)).toEqual([{
      scheme: 'digest',
      params: {
        realm: 'digest-lab',
        nonce: 'abc123',
        opaque: 'deadbeef',
        algorithm: 'MD5',
        qop: 'auth'
      }
    }]);
  });

  it('keeps commas inside quoted values within one parameter', () => {
    const header = 'Digest realm="a, b", nonce="n1", qop="auth-int,auth"';
    expect(parseChallenges(header)).toEqual([{
      scheme: 'digest',
      params: { realm: 'a, b', nonce: 'n1', qop: 'auth-int,auth' }
    }]);
  });

  it('separates multiple challenges merged into one header value', () => {
    const header = 'Basic realm="basic-zone", Digest realm="digest-zone", nonce="n2", qop="auth"';
    expect(parseChallenges(header)).toEqual([
      { scheme: 'basic', params: { realm: 'basic-zone' } },
      { scheme: 'digest', params: { realm: 'digest-zone', nonce: 'n2', qop: 'auth' } }
    ]);
  });

  it('unescapes backslash escapes inside quoted values', () => {
    expect(parseChallenges('Digest realm="say \\"hi\\"", nonce="n"')).toEqual([
      { scheme: 'digest', params: { realm: 'say "hi"', nonce: 'n' } }
    ]);
  });

  it('reads a parameter with whitespace around its = as a parameter, not a scheme', () => {
    expect(parseChallenges('Digest realm="r", qop = "auth", nonce = "n"')).toEqual([
      { scheme: 'digest', params: { realm: 'r', qop: 'auth', nonce: 'n' } }
    ]);
  });
});

describe('findDigestChallenge', () => {
  it('finds the digest challenge when another scheme is listed first', () => {
    const header = 'Basic realm="basic-zone", Digest realm="digest-zone", nonce="n2", qop="auth"';
    expect(findDigestChallenge(header)).toEqual({ realm: 'digest-zone', nonce: 'n2', qop: 'auth' });
  });

  it('prefers the MD5 digest challenge when the server offers several (RFC 7616)', () => {
    const header
      = 'Digest realm="r", nonce="sha", algorithm=SHA-256, qop="auth", '
        + 'Digest realm="r", nonce="md5", algorithm=MD5, qop="auth"';
    expect(findDigestChallenge(header)).toEqual({ realm: 'r', nonce: 'md5', algorithm: 'MD5', qop: 'auth' });
  });

  it('returns the unsupported digest challenge when no MD5 variant exists', () => {
    const header = 'Digest realm="r", nonce="sha", algorithm=SHA-256';
    expect(findDigestChallenge(header)).toEqual({ realm: 'r', nonce: 'sha', algorithm: 'SHA-256' });
  });

  it('returns null when no digest challenge is offered', () => {
    expect(findDigestChallenge('Basic realm="x"')).toBeNull();
    expect(findDigestChallenge('Negotiate')).toBeNull();
  });
});

describe('buildDigestAuthorization', () => {
  it('reproduces the RFC 2617 worked example byte-for-byte', () => {
    const result = buildDigestAuthorization({
      challenge: RFC_CHALLENGE,
      method: 'GET',
      uri: '/dir/index.html',
      username: 'Mufasa',
      password: 'Circle Of Life',
      cnonce: '0a4f113b'
    });
    expect(result).toEqual({
      ok: true,
      header:
        'Digest username="Mufasa", realm="testrealm@host.com", nonce="dcd98b7102dd2f0e8b11d0f600bfb0c093", '
        + 'uri="/dir/index.html", response="6629fae49393a05397450978507c4ef1", qop=auth, algorithm=MD5, '
        + 'nc=00000001, cnonce="0a4f113b", opaque="5ccc069c403ebaf9f0171e9517f40e41"'
    });
  });

  it('escapes quotes and backslashes in quoted header fields', () => {
    const result = buildDigestAuthorization({
      challenge: { realm: 'realm "x"', nonce: 'n\\1', qop: 'auth' },
      method: 'GET',
      uri: '/',
      username: 'user"with\\quirks',
      password: 'p',
      cnonce: '0a4f113b'
    });
    expect(result.ok).toBe(true);
    const header = (result as { ok: true; header: string }).header;
    expect(header).toContain('username="user\\"with\\\\quirks"');
    expect(header).toContain('realm="realm \\"x\\""');
    expect(header).toContain('nonce="n\\\\1"');
  });

  it('rejects a qop list that does not offer auth', () => {
    expect(buildDigestAuthorization({
      challenge: { ...RFC_CHALLENGE, qop: 'auth-int' },
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    })).toEqual({ ok: false, reason: 'unsupported-qop' });
  });

  it('uses the legacy no-qop form when the challenge omits qop', () => {
    const result = buildDigestAuthorization({
      challenge: { realm: RFC_CHALLENGE.realm, nonce: RFC_CHALLENGE.nonce, opaque: RFC_CHALLENGE.opaque },
      method: 'GET',
      uri: '/dir/index.html',
      username: 'Mufasa',
      password: 'Circle Of Life'
    });
    expect(result).toEqual({
      ok: true,
      header:
        'Digest username="Mufasa", realm="testrealm@host.com", nonce="dcd98b7102dd2f0e8b11d0f600bfb0c093", '
        + 'uri="/dir/index.html", response="670fd8c2df070c60b045671b8b24ff02", opaque="5ccc069c403ebaf9f0171e9517f40e41"'
    });
  });

  it('rejects a challenge missing realm or nonce', () => {
    expect(buildDigestAuthorization({
      challenge: { nonce: 'abc' },
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    })).toEqual({ ok: false, reason: 'malformed-challenge' });
    expect(buildDigestAuthorization({
      challenge: { realm: 'r' },
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    })).toEqual({ ok: false, reason: 'malformed-challenge' });
  });

  it('rejects non-MD5 algorithms like the desktop app does', () => {
    expect(buildDigestAuthorization({
      challenge: { ...RFC_CHALLENGE, algorithm: 'SHA-256' },
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    })).toEqual({ ok: false, reason: 'unsupported-algorithm' });
  });

  it('generates a 48-char hex cnonce when none is injected', () => {
    const result = buildDigestAuthorization({
      challenge: RFC_CHALLENGE,
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    });
    expect(result.ok).toBe(true);
    expect((result as { ok: true; header: string }).header).toMatch(/cnonce="[0-9a-f]{48}"/);
  });

  it('hashes non-ASCII credentials as UTF-8 bytes, matching the desktop app', () => {
    const result = buildDigestAuthorization({
      challenge: { realm: 'digest-lab', nonce: 'abc123def', qop: 'auth' },
      method: 'GET',
      uri: '/data',
      username: 'grüße',
      password: 'päss123',
      cnonce: '0a4f113b'
    });
    expect(result.ok).toBe(true);
    expect((result as { ok: true; header: string }).header).toContain('response="ee64327486c840299318b6c95455fb54"');
  });

  it('rejects a challenge whose echoed values carry control characters', () => {
    expect(buildDigestAuthorization({
      challenge: { ...RFC_CHALLENGE, realm: 'evil\r\nX-Injected: 1' },
      method: 'GET',
      uri: '/',
      username: 'u',
      password: 'p'
    })).toEqual({ ok: false, reason: 'malformed-challenge' });
  });
});

describe('getDigestCredentials', () => {
  it('returns the credentials for a digest config', () => {
    expect(getDigestCredentials({ type: 'digest', username: 'u', password: 'p' }))
      .toEqual({ username: 'u', password: 'p' });
  });

  it('normalizes an absent password to an empty string instead of disabling the flow', () => {
    expect(getDigestCredentials({ type: 'digest', username: 'u' }))
      .toEqual({ username: 'u', password: '' });
  });

  it('returns null for other auth types and for an unusable username', () => {
    expect(getDigestCredentials(undefined)).toBeNull();
    expect(getDigestCredentials({ type: 'basic', username: 'u', password: 'p' })).toBeNull();
    expect(getDigestCredentials({ type: 'digest', username: '', password: 'p' })).toBeNull();
    expect(getDigestCredentials({ type: 'digest', password: 'p' })).toBeNull();
  });
});

import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { parse } from 'node-html-parser';
import { describe, it, expect } from 'vitest';
import { AuthDetails } from './AuthDetails';
import { AUTH_MODE_LABELS } from '@/constants';
import { SECRET_MASK } from '@/constants';

const renderAuth = (ui: React.ReactElement) => {
  const html = renderToStaticMarkup(ui);
  const root = parse(html);
  // Strip emotion's inline <style> blocks so their CSS text never counts as content.
  root.querySelectorAll('style').forEach((style) => style.remove());
  const getByTestId = (testId: string) => {
    const element = root.querySelector(`[data-testid="${testId}"]`);
    if (!element) throw new Error(`No element with data-testid="${testId}"`);
    return element;
  };
  return { html, getByTestId };
};

describe('AuthDetails', () => {
  it('renders basic auth: mode + username, masks the password', () => {
    const { getByTestId, html } = renderAuth(
      <AuthDetails
        auth={{ type: 'basic', username: 'user@example.com', password: 's3cr3t' }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-mode').text.trim()).toBe('Basic Auth');
    expect(getByTestId('auth-username').text.trim()).toBe('user@example.com');
    expect(getByTestId('auth-password').text.trim()).toBe(SECRET_MASK);
    expect(html).not.toContain('s3cr3t');
  });

  it('masks the bearer token and falls back to the raw type without a label', () => {
    const { getByTestId, html } = renderAuth(<AuthDetails auth={{ type: 'bearer', token: 'abc123' }} testId="auth" />);
    expect(getByTestId('auth-mode').text.trim()).toBe('bearer');
    expect(getByTestId('auth-token').text.trim()).toBe(SECRET_MASK);
    expect(html).not.toContain('abc123');
  });

  it('renders apikey fields and humanizes the placement', () => {
    const { getByTestId } = renderAuth(
      <AuthDetails
        auth={{ type: 'apikey', key: 'X-Api-Key', value: 'k', placement: 'header' }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-mode').text.trim()).toBe('API Key');
    expect(getByTestId('auth-key').text.trim()).toBe('X-Api-Key');
    expect(getByTestId('auth-add-to').text.trim()).toBe('Header');
  });

  it('humanizes a query-params placement', () => {
    const { getByTestId } = renderAuth(
      <AuthDetails
        auth={{ type: 'apikey', key: 'api_key', value: 'k', placement: 'query' }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-add-to').text.trim()).toBe('Query Params');
  });

  it('renders AWS Signature v4 fields and masks the secret + session token', () => {
    const { getByTestId, html } = renderAuth(
      <AuthDetails
        auth={{
          type: 'awsv4',
          accessKeyId: 'AKIAEXAMPLE',
          secretAccessKey: 'secretKeyValue',
          sessionToken: '[REDACTED]',
          service: 'execute-api',
          region: 'us-east-1',
          profileName: 'default'
        }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-mode').text.trim()).toBe('AWS Signature v4');
    expect(getByTestId('auth-access-key-id').text.trim()).toBe('AKIAEXAMPLE');
    expect(getByTestId('auth-service').text.trim()).toBe('execute-api');
    expect(getByTestId('auth-region').text.trim()).toBe('us-east-1');
    expect(getByTestId('auth-secret-access-key').text.trim()).toBe(SECRET_MASK);
    expect(getByTestId('auth-session-token').text.trim()).toBe(SECRET_MASK);
    expect(html).not.toContain('secretKeyValue');
    expect(html).not.toContain('sessionTokenValue');
  });

  it('renders the full oauth1 field set and masks the private key', () => {
    const { getByTestId, html } = renderAuth(
      <AuthDetails
        auth={{
          type: 'oauth1',
          consumerKey: 'ck',
          privateKey: { type: 'text', value: 'pem-secret' },
          verifier: 'v-code',
          timestamp: '1700000000',
          nonce: 'n-123',
          version: '1.0',
          realm: 'my-realm',
          includeBodyHash: true,
          placement: 'body'
        }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-verifier').text.trim()).toBe('v-code');
    expect(getByTestId('auth-nonce').text.trim()).toBe('n-123');
    expect(getByTestId('auth-realm').text.trim()).toBe('my-realm');
    expect(getByTestId('auth-include-body-hash').text.trim()).toBe('Yes');
    expect(getByTestId('auth-placement').text.trim()).toBe('Body');
    expect(getByTestId('auth-private-key').text.trim()).toBe(SECRET_MASK);
    expect(html).not.toContain('pem-secret');
  });

  it('renders oauth2 authorization-code details: refresh url, state, pkce, token config, settings', () => {
    const { getByTestId } = renderAuth(
      <AuthDetails
        auth={{
          type: 'oauth2',
          flow: 'authorization_code',
          authorizationUrl: 'https://auth',
          accessTokenUrl: 'https://token',
          refreshTokenUrl: 'https://refresh',
          state: 'xyz',
          scope: 'read write',
          credentials: { clientId: 'cid', clientSecret: 'csecret', placement: 'basic_auth_header' },
          pkce: { method: 'S256' },
          tokenConfig: { source: 'id_token', placement: { header: 'Authorization' } },
          settings: { autoFetchToken: true, autoRefreshToken: false }
        }}
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-flow').text.trim()).toBe('Authorization Code');
    expect(getByTestId('auth-refresh-token-url').text.trim()).toBe('https://refresh');
    expect(getByTestId('auth-state').text.trim()).toBe('xyz');
    expect(getByTestId('auth-pkce').text.trim()).toBe('S256');
    expect(getByTestId('auth-add-credentials-to').text.trim()).toBe('Basic Auth Header');
    expect(getByTestId('auth-token-source').text.trim()).toBe('ID Token');
    expect(getByTestId('auth-token-placement').text.trim()).toBe('Header (Authorization)');
    expect(getByTestId('auth-auto-fetch-token').text.trim()).toBe('Yes');
    expect(getByTestId('auth-auto-refresh-token').text.trim()).toBe('No');
  });

  it('renders oauth2 additional parameters grouped by request phase', () => {
    const { getByTestId } = renderAuth(
      <AuthDetails
        auth={
          {
            type: 'oauth2',
            flow: 'authorization_code',
            accessTokenUrl: 'https://token',
            additionalParameters: {
              authorizationRequest: [{ name: 'audience', value: 'https://api', placement: 'query' }],
              accessTokenRequest: [{ name: 'resource', value: 'r1', placement: 'body' }]
            }
          } as any
        }
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    const audience = getByTestId('auth-additional-param-authorizationRequest-0');
    const audienceRow = audience.parentNode;
    expect(audience.text.trim()).toBe('https://api');
    expect(audienceRow.querySelector('.property-key')?.text.trim()).toBe('audience');
    expect(audienceRow.querySelector('.description')?.text.trim()).toBe('Authorization Request · Query Params');

    const resource = getByTestId('auth-additional-param-accessTokenRequest-0');
    const resourceRow = resource.parentNode;
    expect(resource.text.trim()).toBe('r1');
    expect(resourceRow.querySelector('.property-key')?.text.trim()).toBe('resource');
    expect(resourceRow.querySelector('.description')?.text.trim()).toBe('Access Token Request · Body');
  });

  it('renders Akamai EdgeGrid auth and masks the secret credentials', () => {
    const { getByTestId, html } = renderAuth(
      <AuthDetails
        auth={
          {
            type: 'akamai-edgegrid',
            accessToken: 'atValue',
            clientToken: 'ctValue',
            clientSecret: 'csValue',
            baseURL: 'https://akaa-base.luna.akamaiapis.net',
            nonce: 'n-1',
            timestamp: '20240101T00:00:00+0000',
            headersToSign: 'X-Custom',
            maxBodySize: 2048
          } as any
        }
        authModeLabels={AUTH_MODE_LABELS}
        testId="auth"
      />
    );
    expect(getByTestId('auth-mode').text.trim()).toBe('Akamai EdgeGrid');
    expect(getByTestId('auth-base-url').text.trim()).toBe('https://akaa-base.luna.akamaiapis.net');
    expect(getByTestId('auth-headers-to-sign').text.trim()).toBe('X-Custom');
    expect(getByTestId('auth-max-body-size').text.trim()).toBe('2048');
    expect(getByTestId('auth-access-token').text.trim()).toBe(SECRET_MASK);
    expect(getByTestId('auth-client-token').text.trim()).toBe(SECRET_MASK);
    expect(getByTestId('auth-client-secret').text.trim()).toBe(SECRET_MASK);
    expect(html).not.toContain('atValue');
    expect(html).not.toContain('ctValue');
    expect(html).not.toContain('csValue');
  });

  it('shows the empty message when there is no auth', () => {
    const { getByTestId } = renderAuth(<AuthDetails emptyMessage="No authentication configured" testId="auth" />);
    expect(getByTestId('auth-empty').text.trim()).toBe('No authentication configured');
  });
});

import { test, expect } from '../../playwright';
import type { Page } from '@playwright/test';
import type { CodeEditorComponent } from '../../components/code-editor/code-editor.component';
import type { PlaygroundComponent } from '../../components/playground.component';

const SCRIPT_AUTHORIZATION = 'Bearer script-token';
const CONFIG_TOKEN = '[REDACTED]';

const TAB_AUTHORIZATION = 'Bearer tab-token';

const SET_AUTHORIZATION_SCRIPT = `req.setHeader('authorization', '${SCRIPT_AUTHORIZATION}');`;
const SET_API_KEY_HEADER_SCRIPT = `req.setHeader('x-api-key', 'script-key');`;

const setEditorScript = async (page: Page, editor: CodeEditorComponent, script: string): Promise<void> => {
  await editor.focus();
  await page.keyboard.press('ControlOrMeta+a');
  await page.keyboard.insertText(script);
};

const addAuthorizationHeaderRow = async (playground: PlaygroundComponent): Promise<void> => {
  await playground.selectTab('headers');
  const { keyValueTable } = playground;
  const rowIndex = (await keyValueTable.nameInputs.count()) - 1;
  await keyValueTable.nameInputs.nth(rowIndex).fill('Authorization');
  await keyValueTable.valueInputs.nth(rowIndex).fill(TAB_AUTHORIZATION);
};

test.describe('auth header precedence between the Headers tab, the Auth tab and a pre-request script', () => {
  test.use({ viewport: { width: 1280, height: 900 } });

  test.beforeEach(async ({ playground, responsePane }) => {
    await responsePane.mockUsersResponse(JSON.stringify({ users: [] }));
    await playground.open('bottom');
    await playground.openRequest('get users');
    await playground.selectTab('auth');
    await playground.auth.selectMode('bearer');
    await playground.auth.field('token').fill(CONFIG_TOKEN);
  });

  test('a pre-request script that sets Authorization sends the script value instead of the configured bearer token', async ({ page, playground, responsePane }) => {
    await playground.selectTab('scripts');
    await setEditorScript(page, playground.preRequestScriptEditor, SET_AUTHORIZATION_SCRIPT);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(SCRIPT_AUTHORIZATION);
  });

  test('an Authorization row in the Headers tab is overwritten by the configured bearer token, as on desktop', async ({ playground, responsePane }) => {
    await addAuthorizationHeaderRow(playground);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(`Bearer ${CONFIG_TOKEN}`);
  });

  test('a pre-request script overwriting the Headers tab Authorization row wins over both tabs', async ({ page, playground, responsePane }) => {
    await addAuthorizationHeaderRow(playground);
    await playground.selectTab('scripts');
    await setEditorScript(page, playground.preRequestScriptEditor, SET_AUTHORIZATION_SCRIPT);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(SCRIPT_AUTHORIZATION);
  });

  test('with Basic auth configured, a pre-request script Authorization header is overwritten, as on desktop', async ({ page, playground, responsePane }) => {
    await playground.auth.selectMode('basic');
    await playground.auth.field('username').fill('user');
    await playground.auth.field('password').fill('pass');
    await playground.selectTab('scripts');
    await setEditorScript(page, playground.preRequestScriptEditor, SET_AUTHORIZATION_SCRIPT);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(`Basic ${Buffer.from('user:pass').toString('base64')}`);
  });

  test('with api key auth in header placement, a pre-request script setting that header wins', async ({ page, playground, responsePane }) => {
    await playground.auth.selectMode('apikey');
    await playground.auth.field('key').fill('X-API-Key');
    await playground.auth.field('value').fill('config-key');
    await playground.selectTab('scripts');
    await setEditorScript(page, playground.preRequestScriptEditor, SET_API_KEY_HEADER_SCRIPT);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['x-api-key']).toBe('script-key');
  });

  test('with No Auth selected, the Headers tab Authorization row is sent as typed', async ({ playground, responsePane }) => {
    await playground.auth.selectMode('none');
    await addAuthorizationHeaderRow(playground);

    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(TAB_AUTHORIZATION);
  });

  test('without a competing header the configured bearer token is sent', async ({ responsePane }) => {
    const sent = responsePane.waitForUsersRequest();
    await responsePane.send();
    const request = await sent;

    expect(request.headers()['authorization']).toBe(`Bearer ${CONFIG_TOKEN}`);
  });
});

import { test, expect } from '../../playwright';
import type { PlaygroundComponent } from '../../components/playground.component';

const EXPECTED_AUTHORIZATION
  = /^Digest username="user", realm="digest-lab", nonce="[0-9a-f]{32}", uri="\/api\/users\?page=1&limit=10", response="[0-9a-f]{32}", qop=auth, algorithm=MD5, nc=00000001, cnonce="[0-9a-f]{48}", opaque="deadbeef"$/;

const configureDigest = async (
  playground: PlaygroundComponent,
  { requestName = 'get users', username = 'user', password = 'pass' } = {}
): Promise<void> => {
  await playground.openRequest(requestName);
  await playground.selectTab('auth');
  await playground.auth.selectMode('digest');
  await playground.auth.field('username').fill(username);
  await playground.auth.field('password').fill(password);
};

test.describe('digest auth', () => {
  test.beforeEach(async ({ playground }) => {
    await playground.open('bottom');
  });

  test('completes the challenge handshake and shows the authenticated response', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock();

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    await expect(responsePane.bodyPanel).toContainText('authenticated');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[0].authorization).toBeNull();
    expect(mock.requests[1].authorization).toMatch(EXPECTED_AUTHORIZATION);
  });

  test('authenticates against a legacy server that omits qop', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({ qop: null });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).not.toContain('qop=');
  });

  test('shows the second 401 as a normal response for wrong credentials', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock();

    await configureDigest(playground, { password: 'wrong' });
    await responsePane.send();

    await expect(responsePane.status).toContainText('401');
    await expect(responsePane.errorBanner).toBeHidden();
    expect(mock.requests).toHaveLength(2);
  });

  test('explains a challenge the server sent but did not expose to the browser', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({ exposeChallenge: false });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.errorTitle).toHaveText('Couldn\'t read the digest challenge');
    await expect(responsePane.errorMessage).toContainText('Access-Control-Expose-Headers');
    expect(mock.requests).toHaveLength(1);
  });

  test('explains a cross-origin 401 that carries no challenge at all', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({ sendChallenge: false });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.errorTitle).toHaveText('Couldn\'t read the digest challenge');
    await expect(responsePane.errorMessage).toContainText('either the server didn\'t send one');
    expect(mock.requests).toHaveLength(1);
  });

  test('explains a malformed challenge missing realm and nonce', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({ challengeOverride: 'Digest qop="auth"' });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.errorTitle).toHaveText('Couldn\'t complete digest auth');
    expect(mock.requests).toHaveLength(1);
  });

  test('passes a non-digest 401 through as the final response', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({ challengeOverride: 'Basic realm="digest-lab"' });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.status).toContainText('401');
    await expect(responsePane.errorBanner).toBeHidden();
    expect(mock.requests).toHaveLength(1);
  });

  test('completes the handshake when Basic is offered ahead of Digest', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({
      challengeOverride:
        'Basic realm="digest-lab", Digest realm="digest-lab", nonce="feedbeefcafe", opaque="deadbeef", algorithm=MD5, qop="auth"'
    });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).toMatch(/^Digest username="user", realm="digest-lab"/);
  });

  test('rejects a non-MD5 challenge with a clear error', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock({
      challengeOverride: 'Digest realm="digest-lab", nonce="abc123", algorithm=SHA-256, qop="auth"'
    });

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.errorTitle).toHaveText('Unsupported digest algorithm');
    expect(mock.requests).toHaveLength(1);
  });

  test('uploads the POST body on both the challenged leg and the signed retry', async ({ playground, responsePane, digestMock }) => {
    const mock = await digestMock();

    await configureDigest(playground, { requestName: 'echo json' });
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[0].postData).not.toBeNull();
    expect(mock.requests[1].postData).toBe(mock.requests[0].postData);
  });

  test('a request-level digest config overrides the collection auth', async ({ playground, responsePane, collectionSettings, digestMock }) => {
    const mock = await digestMock();

    await playground.ensureSidebarOpen();
    await collectionSettings.open();
    await collectionSettings.openTab('auth');
    await collectionSettings.selectAuthMode('digest');
    await collectionSettings.authField('username').fill('user');
    await collectionSettings.authField('password').fill('collection-wrong');

    await configureDigest(playground);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).toMatch(EXPECTED_AUTHORIZATION);
  });
});

test.describe('digest auth — inheritance and variables', () => {
  test.use({ viewport: { width: 1400, height: 900 } });

  test.beforeEach(async ({ playground }) => {
    await playground.open('inline');
  });

  test('applies collection-level digest through the inherit chain with an env-var url', async ({ playground, responsePane, collectionSettings, envEditor, digestMock }) => {
    const mock = await digestMock();

    await playground.openEnvironments();
    await envEditor.addVariable('baseUrl', 'http://localhost:8081');

    await playground.ensureSidebarOpen();
    await collectionSettings.open();
    await collectionSettings.openTab('auth');
    await collectionSettings.selectAuthMode('digest');
    await collectionSettings.authField('username').fill('user');
    await collectionSettings.authField('password').fill('pass');

    await playground.openTreeItem(['billing', 'customers', 'Get All Customers']);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).toMatch(/^Digest username="user", realm="digest-lab"/);
  });

  test('applies digest configured on the closest folder to an inheriting request', async ({ playground, responsePane, envEditor, digestMock }) => {
    const mock = await digestMock();

    await playground.openEnvironments();
    await envEditor.addVariable('baseUrl', 'http://localhost:8081');

    await playground.openTreeItem(['billing', 'customers']);
    await playground.folderSettingsTab('auth').click();
    await playground.auth.selectMode('digest');
    await playground.auth.field('username').fill('user');
    await playground.auth.field('password').fill('pass');

    await playground.openTreeItem(['Get All Customers']);
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).toMatch(/^Digest username="user", realm="digest-lab"/);
  });

  test('resolves {{variables}} in the digest username and password', async ({ playground, responsePane, envEditor, digestMock }) => {
    const mock = await digestMock();

    await playground.openEnvironments();
    await envEditor.addVariable('digest_user', 'user');
    await envEditor.addVariable('digest_pass', 'pass');

    await configureDigest(playground, { username: '{{digest_user}}', password: '[REDACTED]}}' });
    await responsePane.send();

    await expect(responsePane.status).toContainText('200');
    expect(mock.requests).toHaveLength(2);
    expect(mock.requests[1].authorization).toMatch(EXPECTED_AUTHORIZATION);
  });
});

import { test, expect } from '../../playwright';

const DESKTOP = { width: 1280, height: 900 };

test.describe('Playground request — inherited auth', () => {
  test.use({ viewport: DESKTOP });

  test('the auth dropdown offers Inherit alongside the five supported types, and nothing more', async ({
    playground
  }) => {
    await playground.open('bottom');
    await playground.openRequest('get users');
    await playground.selectTab('auth');

    await playground.auth.open();
    await expect(playground.auth.option('none')).toBeVisible();
    await expect(playground.auth.option('inherit')).toBeVisible();
    await expect(playground.auth.option('basic')).toBeVisible();
    await expect(playground.auth.option('bearer')).toBeVisible();
    await expect(playground.auth.option('apikey')).toBeVisible();
    await expect(playground.auth.option('digest')).toBeVisible();
    // No Auth + Inherit + Basic + Bearer + API Key + Digest — no other auth types are offered.
    await expect(playground.auth.options).toHaveCount(6);
  });

  test('choosing Inherit shows the inherited-auth notice and marks the mode selected', async ({
    playground
  }) => {
    await playground.open('bottom');
    await playground.openRequest('get users');
    await playground.selectTab('auth');

    await playground.auth.selectMode('inherit');
    await expect(playground.auth.modeSelect).toContainText('Inherit');
    await expect(playground.auth.inheritNotice).toBeVisible();
  });

  test('a request already set to inherit opens with Inherit preselected', async ({ playground }) => {
    await playground.open('bottom');
    // Get All Customers inherits its auth from the Bearer-authed collection.
    await playground.openTreeItem(['billing', 'customers', 'Get All Customers']);
    await playground.selectTab('auth');

    await expect(playground.auth.modeSelect).toContainText('Inherit');
    await expect(playground.auth.inheritNotice).toBeVisible();
  });
});

import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { parse } from 'node-html-parser';
import { Provider } from 'react-redux';
import { describe, it, expect } from 'vitest';
import type { RunRequestResponse } from '@/runner';
import { createOpenCollectionStore } from '@/store/store';
import { query, getByTestId } from '@/test-utils/dom';
import ResponseActions from './ResponseActions';

const baseResponse: RunRequestResponse = {
  status: 200,
  headers: { 'content-type': 'application/json' },
  data: { hello: 'world' },
  base64Data: Buffer.from('{"hello":"world"}').toString('base64'),
  url: 'http://localhost:8081/api/users'
};

const render = (props: Partial<React.ComponentProps<typeof ResponseActions>> = {}) => {
  const store = createOpenCollectionStore();
  const root = parse(
    renderToStaticMarkup(
      <Provider store={store}>
        <ResponseActions
          orientation="horizontal"
          itemUuid="item-1"
          response={baseResponse}
          selectedFormat="json"
          showPreview={false}
          {...props}
        />
      </Provider>
    )
  );
  root.querySelectorAll('style').forEach((style) => style.remove());
  return root;
};

// Buttons render in two mirrored groups: an inline `actions-buttons` block (shown when the pane is
// wide) and a collapsed kebab `actions-dropdown` (shown when narrow). CSS toggles which is visible;
// both exist in the static markup. The inline group is the one carrying the individual buttons.
const inlineButton = (root: ReturnType<typeof render>, label: string) =>
  query(getByTestId(root, 'actions-buttons'), `[aria-label="${label}"]`);

describe('ResponseActions', () => {
  it('renders the actions wrapper with both the inline and collapsed groups', () => {
    const root = render();
    expect(getByTestId(root, 'response-pane-actions-wrapper')).toBeTruthy();
    expect(getByTestId(root, 'actions-buttons')).toBeTruthy();
    expect(getByTestId(root, 'actions-dropdown')).toBeTruthy();
  });

  it('exposes Copy, Download, Clear and Change Layout as inline icon buttons', () => {
    const root = render();
    expect(inlineButton(root, 'Copy Response')).toBeTruthy();
    expect(inlineButton(root, 'Download Response')).toBeTruthy();
    expect(inlineButton(root, 'Clear Response')).toBeTruthy();
    expect(inlineButton(root, 'Change Layout')).toBeTruthy();
  });

  describe('Copy Response', () => {
    it('shows the copy icon and is enabled when the response has data', () => {
      const button = inlineButton(render(), 'Copy Response');
      expect(button.innerHTML).toContain('icon-tabler-copy');
      expect(button.innerHTML).not.toContain('icon-tabler-check');
      expect(button.hasAttribute('disabled')).toBe(false);
    });

    it('is disabled when the response has no data', () => {
      const button = inlineButton(render({ response: { ...baseResponse, data: undefined } }), 'Copy Response');
      expect(button.hasAttribute('disabled')).toBe(true);
    });
  });

  describe('Download Response', () => {
    it('shows the download icon and is enabled when raw bytes are present', () => {
      const button = inlineButton(render(), 'Download Response');
      expect(button.innerHTML).toContain('icon-tabler-download');
      expect(button.hasAttribute('disabled')).toBe(false);
    });

    it('is disabled when the response carries no base64 bytes', () => {
      const button = inlineButton(render({ response: { ...baseResponse, base64Data: undefined } }), 'Download Response');
      expect(button.hasAttribute('disabled')).toBe(true);
    });
  });

  describe('Clear Response', () => {
    it('shows the eraser icon and is always enabled', () => {
      const button = inlineButton(render(), 'Clear Response');
      expect(button.innerHTML).toContain('icon-tabler-eraser');
      expect(button.hasAttribute('disabled')).toBe(false);
    });

    it('stays enabled even when there is nothing to copy or download', () => {
      const button = inlineButton(
        render({ response: { ...baseResponse, data: undefined, base64Data: undefined } }),
        'Clear Response'
      );
      expect(button.hasAttribute('disabled')).toBe(false);
    });
  });

  describe('Change Layout', () => {
    it('shows the columns icon in the vertical orientation', () => {
      const button = inlineButton(render({ orientation: 'vertical' }), 'Change Layout');
      expect(button.innerHTML).toContain('icon-tabler-layout-columns');
      expect(button.innerHTML).not.toContain('icon-tabler-layout-rows');
    });

    it('shows the rows icon in the horizontal orientation', () => {
      const button = inlineButton(render({ orientation: 'horizontal' }), 'Change Layout');
      expect(button.innerHTML).toContain('icon-tabler-layout-rows');
      expect(button.innerHTML).not.toContain('icon-tabler-layout-columns');
    });
  });

  describe('buttons-only rendering', () => {
    it('renders buttons-only with no testids or dropdown so the tab bar can measure its width', () => {
      const root = render({ renderActionButtonsOnly: true });
      getByTestId(root, 'forceful-renderred-action-buttons');
      expect(query(root, '[aria-label="Copy Response"]')).toBeTruthy();
      expect(query(root, '[aria-label="Change Layout"]')).toBeTruthy();
      expect(root.querySelector('[aria-label="More actions"]')).toBeNull();
    });
  });

  describe('collapsed kebab menu', () => {
    it('renders the "More actions" dropdown trigger, closed by default', () => {
      const root = render();
      const trigger = query(getByTestId(root, 'actions-dropdown'), '[data-testid="response-actions-menu"]');
      expect(trigger.getAttribute('aria-label')).toBe('More actions');
      expect(trigger.getAttribute('aria-haspopup')).toBe('menu');
      expect(trigger.getAttribute('aria-expanded')).toBe('false');
      expect(trigger.innerHTML).toContain('icon-tabler-dots');
      // Closed: the menu surface and its items are not in the static markup.
      expect(root.querySelector('[role="menu"]')).toBeNull();
    });
  });
});

import React from 'react';
import { renderToStaticMarkup } from 'react-dom/server';
import { parse } from 'node-html-parser';
import { describe, it, expect } from 'vitest';
import { getByTestId, query } from '@/test-utils/dom';
import { AUTH_DEFAULTS, AUTH_MODE_LABELS, PLACEMENT_OPTIONS } from '@/constants';
import { AuthTab } from './AuthTab';

const render = (ui: React.ReactElement) => {
  const root = parse(renderToStaticMarkup(ui));
  root.querySelectorAll('style').forEach((style) => style.remove());
  const byTestId = (testId: string) => root.querySelector(`[data-testid="${testId}"]`);
  const getByTestId = (testId: string) => {
    const el = byTestId(testId);
    if (!el) throw new Error(`No element with data-testid="${testId}"`);
    return el;
  };
  return { root, byTestId, getByTestId };
};

const noop = () => {};

const renderAuth = (auth: unknown, extra: Record<string, unknown> = {}) =>
  render(<AuthTab auth={auth} onAuthChange={noop} showFullAuth item={{ request: {} }} onItemChange={noop} {...extra} />);

describe('AuthTab', () => {
  it('offers exactly the five supported auth types and none of the unsupported ones', () => {
    const modeLabels = ['No Auth', ...Object.keys(AUTH_DEFAULTS).map((mode) => AUTH_MODE_LABELS[mode] ?? mode)];
    expect(modeLabels).toEqual(['No Auth', 'Basic Auth', 'Bearer Token', 'API Key', 'Digest Auth']);
    ['aws', 'signature', 'oauth', 'wsse', 'ntlm', 'edgegrid', 'akamai'].forEach((excluded) =>
      expect(modeLabels.join(' ').toLowerCase()).not.toContain(excluded)
    );
  });

  it('shows the current auth type on the mode trigger', () => {
    expect(renderAuth(undefined).getByTestId('auth-mode-select').text).toContain('No Auth');
    expect(renderAuth({ type: 'bearer', token: 'abc' }).getByTestId('auth-mode-select').text).toContain('Bearer Token');
    expect(renderAuth({ type: 'digest', username: 'u', password: 'p' }).getByTestId('auth-mode-select').text).toContain('Digest Auth');
  });

  it('offers Inherit as a mode only when showInherit is set', () => {
    // Enabled: inherit is selectable and shows on the trigger.
    expect(renderAuth('inherit', { showInherit: true }).getByTestId('auth-mode-select').text).toContain('Inherit');
    // Disabled: inherit is not an option, so nothing matches and the trigger shows no label.
    expect(renderAuth('inherit').getByTestId('auth-mode-select').text.trim()).toBe('');
  });

  it('renders no form for None', () => {
    const { root, byTestId } = renderAuth(undefined);
    expect(root.querySelector('.auth-form')).toBeNull();
    expect(byTestId('auth-username')).toBeNull();
    expect(getByTestId(root, 'no-content-text').text.trim()).toBe('No authentication configured.');
  });

  it('names the inherited source and its effective mode, matching the app', () => {
    const { root, getByTestId } = renderAuth('inherit', {
      showInherit: true,
      inheritedAuth: { sourceName: 'Users', modeLabel: 'Bearer Token' }
    });
    expect(query(root, '.auth-empty').text.replace(/\s+/g, ' ').trim()).toBe('Auth inherited from Users: Bearer Token');
    expect(getByTestId('inherited-auth-mode').text.trim()).toBe('Bearer Token');
  });

  it('falls back to a generic inherit note when the source is not resolved', () => {
    const { root } = renderAuth('inherit', { showInherit: true });
    expect(query(root, '.auth-empty').text.trim()).toBe('Auth inherited from the parent folder or collection.');
  });

  it('renders basic auth with a plain username and a masked, revealable password', () => {
    const { getByTestId } = renderAuth({ type: 'basic', username: 'admin', password: 's3cr3t' });
    expect(getByTestId('auth-username').getAttribute('type')).toBe('text');
    expect(getByTestId('auth-username').getAttribute('value')).toBe('admin');
    expect(getByTestId('auth-password').getAttribute('type')).toBe('password');
    expect(getByTestId('auth-password-toggle').getAttribute('aria-label')).toBe('Show value');
  });

  it('masks the bearer token and exposes a reveal toggle', () => {
    const { getByTestId } = renderAuth({ type: 'bearer', token: 'abc' });
    expect(getByTestId('auth-token').getAttribute('type')).toBe('password');
    expect(getByTestId('auth-token-toggle')).toBeTruthy();
  });

  it('renders apikey with an unmasked value and a header/query placement select', () => {
    const { getByTestId } = renderAuth({ type: 'apikey', key: 'X-Api-Key', value: 'k', placement: 'query' });
    expect(getByTestId('auth-key').getAttribute('type')).toBe('text');
    expect(getByTestId('auth-value').getAttribute('type')).toBe('text');
