import React from 'react';
import type {
  Auth,
  OAuth2ClientCredentials,
  OAuth2ResourceOwner,
  OAuth2PKCE,
  OAuth2TokenConfig,
  OAuth2Settings,
  OAuth2AdditionalParameter
} from '@opencollection/types/common/auth';
import { PropertyTable, type PropertyRow } from '../PropertyTable/PropertyTable';
import { ADDITIONAL_PARAM_GROUPS, AUTH_TYPES } from '@/constants';

interface AuthDetailsProps {
  auth?: Auth;
  authModeLabels?: Record<string, string>;
  inheritedFrom?: string;
  emptyMessage?: string;
  testId?: string;
}

interface OAuth2AuthView {
  flow?: string;
  scope?: string;
  state?: string;
  accessTokenUrl?: string;
  refreshTokenUrl?: string;
  authorizationUrl?: string;
  callbackUrl?: string;
  credentials?: OAuth2ClientCredentials;
  resourceOwner?: OAuth2ResourceOwner;
  pkce?: OAuth2PKCE;
  tokenConfig?: OAuth2TokenConfig;
  settings?: OAuth2Settings;
  additionalParameters?: {
    authorizationRequest?: OAuth2AdditionalParameter[];
    accessTokenRequest?: OAuth2AdditionalParameter[];
    refreshTokenRequest?: OAuth2AdditionalParameter[];
  };
}

interface EdgeGridAuthView {
  type: 'akamai-edgegrid';
  accessToken?: string;
  clientToken?: string;
  clientSecret?: string;
  nonce?: string;
  timestamp?: string;
  baseURL?: string;
  headersToSign?: string;
  maxBodySize?: number;
}

const modeLabel = (auth: Auth, labels: Record<string, string>): string =>
  auth === 'inherit' ? 'Inherit' : labels[auth.type] || auth.type;

/** Humanize the API-key / OAuth placement stored on the schema (e.g. `queryparams` -> `Query Params`). */
const placementLabel = (placement: unknown): string | undefined => {
  if (typeof placement !== 'string' || !placement) return undefined;
  const normalized = placement.toLowerCase().replace(/[_-]/g, '');
  if (normalized === 'header' || normalized === 'headers') return 'Header';
  if (normalized === 'query' || normalized === 'queryparams' || normalized === 'queryparam') return 'Query Params';
  if (normalized === 'body') return 'Body';
  if (normalized === 'basicauthheader') return 'Basic Auth Header';
  return placement;
};

/** Title-case a snake/kebab-cased token, e.g. `authorization_code` -> `Authorization Code`. */
const humanizeToken = (value: unknown): string | undefined => {
  if (typeof value !== 'string' || !value) return undefined;
  return value
    .split(/[_-]/)
    .filter(Boolean)
    .map((word) => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');
};

/** OAuth2 token source (`access_token` / `id_token`) as a friendly label. */
const tokenSourceLabel = (source: unknown): string | undefined =>
  source === 'access_token' ? 'Access Token' : source === 'id_token' ? 'ID Token' : [REDACTED];

/** OAuth2 token placement is `{ header }` or `{ query }` — describe where the token lands. */
const tokenPlacementLabel = (placement: unknown): string | undefined => {
  if (!placement || typeof placement !== 'object') return undefined;
  const p = placement as { header?: string; query?: string };
  if (typeof p.header === 'string') return p.header ? `Header (${p.header})` : 'Header';
  if (typeof p.query === 'string') return p.query ? `Query Params (${p.query})` : 'Query Params';
  return undefined;
};

/** OAuth2 PKCE config -> `Disabled`, the challenge method (e.g. `S256`), or `Enabled`. */
const pkceLabel = (pkce: unknown): string | undefined => {
  if (!pkce || typeof pkce !== 'object') return undefined;
  const p = pkce as { disabled?: boolean; method?: string };
  if (p.disabled) return 'Disabled';
  return p.method || 'Enabled';
};

const pushRow = (rows: PropertyRow[], testId: string, label: string, value: unknown, secret = false): void => {
  if (typeof value === 'string' && value.length > 0) rows.push({ label, value, secret, testId });
};

const pushBool = (rows: PropertyRow[], testId: string, label: string, value: unknown): void => {
  if (typeof value === 'boolean') rows.push({ label, value: value ? 'Yes' : 'No', testId });
};

const pushNumber = (rows: PropertyRow[], testId: string, label: string, value: unknown): void => {
  if (typeof value === 'number' && Number.isFinite(value)) rows.push({ label, value: String(value), testId });
};

const pushAdditionalParameters = (
  rows: PropertyRow[],
  additional: OAuth2AuthView['additionalParameters']
): void => {
  if (!additional) return;
  for (const group of ADDITIONAL_PARAM_GROUPS) {
    const params = additional[group.key];
    if (!Array.isArray(params)) continue;
    params
      .filter((p): p is OAuth2AdditionalParameter => Boolean(p && p.name))
      .forEach((p, index) => {
        const placement = placementLabel(p.placement);
        rows.push({
          label: p.name as string,
          value: p.value ?? '',
          description: `${group.label}${placement ? ` · ${placement}` : ''}`,
          testId: `additional-param-${group.key}-${index}`
        });
      });
  }
};

const buildEdgeGridRows = (auth: EdgeGridAuthView): PropertyRow[] => {
  const rows: PropertyRow[] = [];
  pushRow(rows, 'access-token', 'Access Token', auth.accessToken, true);
  pushRow(rows, 'client-token', 'Client Token', auth.clientToken, true);
  pushRow(rows, 'client-secret', 'Client Secret', auth.clientSecret, true);
  pushRow(rows, 'base-url', 'Base URL', auth.baseURL);
  pushRow(rows, 'nonce', 'Nonce', auth.nonce);
  pushRow(rows, 'timestamp', 'Timestamp', auth.timestamp);
  pushRow(rows, 'headers-to-sign', 'Headers to Sign', auth.headersToSign);
  pushNumber(rows, 'max-body-size', 'Max Body Size', auth.maxBodySize);
  return rows;
};

const buildAuthRows = (auth: Exclude<Auth, 'inherit'>): PropertyRow[] => {
  if ((auth as { type?: string }).type === AUTH_TYPES.EDGEGRID) {
    return buildEdgeGridRows(auth as unknown as EdgeGridAuthView);
  }

  const rows: PropertyRow[] = [];

  switch (auth.type) {
    case AUTH_TYPES.BASIC:
    case AUTH_TYPES.DIGEST:
    case AUTH_TYPES.WSSE:
      pushRow(rows, 'username', 'Username', auth.username);
      pushRow(rows, 'password', 'Password', auth.password, true);
      break;
    case AUTH_TYPES.NTLM:
      pushRow(rows, 'username', 'Username', auth.username);
      pushRow(rows, 'password', 'Password', auth.password, true);
      pushRow(rows, 'domain', 'Domain', auth.domain);
      break;
    case AUTH_TYPES.BEARER:
      pushRow(rows, 'token', 'Token', auth.token, true);
      break;
    case AUTH_TYPES.API_KEY:
      [REDACTED], 'key', 'Key', auth.key);
      pushRow(rows, 'value', 'Value', auth.value, true);
      pushRow(rows, 'add-to', 'Add To', placementLabel(auth.placement));
      break;
    case AUTH_TYPES.AWS_V4:
      pushRow(rows, 'access-key-id', 'Access Key Id', auth.accessKeyId);
      pushRow(rows, 'secret-access-key', 'Secret Access Key', auth.secretAccessKey, true);
      pushRow(rows, 'session-token', 'Session Token', auth.sessionToken, true);
      pushRow(rows, 'service', 'Service', auth.service);
      pushRow(rows, 'region', 'Region', auth.region);
      pushRow(rows, 'profile-name', 'Profile Name', auth.profileName);
      break;
    case AUTH_TYPES.OAUTH1:
      pushRow(rows, 'consumer-key', 'Consumer Key', auth.consumerKey);
      pushRow(rows, 'consumer-secret', 'Consumer Secret', auth.consumerSecret, true);
      pushRow(rows, 'access-token', 'Access Token', auth.accessToken, true);
      pushRow(rows, 'access-token-secret', 'Access Token Secret', auth.accessTokenSecret, true);
      pushRow(rows, 'signature-method', 'Signature Method', auth.signatureMethod);
      pushRow(rows, 'private-key', 'Private Key', auth.privateKey?.value, auth.privateKey?.type !== 'file');
      pushRow(rows, 'callback-url', 'Callback URL', auth.callbackUrl);
      pushRow(rows, 'verifier', 'Verifier', auth.verifier);
      pushRow(rows, 'timestamp', 'Timestamp', auth.timestamp);
      pushRow(rows, 'nonce', 'Nonce', auth.nonce);
      pushRow(rows, 'version', 'Version', auth.version);
      pushRow(rows, 'realm', 'Realm', auth.realm);
      pushBool(rows, 'include-body-hash', 'Include Body Hash', auth.includeBodyHash);
      pushRow(rows, 'placement', 'Placement', placementLabel(auth.placement));
      break;
    case AUTH_TYPES.OAUTH2: {
      const o = auth as OAuth2AuthView;
      pushRow(rows, 'flow', 'Flow', humanizeToken(o.flow));
      pushRow(rows, 'client-id', 'Client Id', o.credentials?.clientId);
      pushRow(rows, 'client-secret', 'Client Secret', o.credentials?.clientSecret, true);
      pushRow(rows, 'add-credentials-to', 'Add Credentials To', placementLabel(o.credentials?.placement));
      pushRow(rows, 'authorization-url', 'Authorization URL', o.authorizationUrl);
      pushRow(rows, 'access-token-url', 'Access Token URL', o.accessTokenUrl);
      pushRow(rows, 'refresh-token-url', 'Refresh Token URL', o.refreshTokenUrl);
      pushRow(rows, 'callback-url', 'Callback URL', o.callbackUrl);
      pushRow(rows, 'scope', 'Scope', o.scope);
      pushRow(rows, 'state', 'State', o.state);
      pushRow(rows, 'pkce', 'PKCE', pkceLabel(o.pkce));
      pushRow(rows, 'token-source', 'Token Source', tokenSourceLabel(o.tokenConfig?.source));
      pushRow(rows, 'token-placement', 'Token Placement', tokenPlacementLabel(o.tokenConfig?.placement));
      pushBool(rows, 'auto-fetch-token', 'Auto Fetch Token', o.settings?.autoFetchToken);
      pushBool(rows, 'auto-refresh-token', 'Auto Refresh Token', o.settings?.autoRefreshToken);
      pushRow(rows, 'username', 'Username', o.resourceOwner?.username);
      pushRow(rows, 'password', 'Password', o.resourceOwner?.password, true);
      pushAdditionalParameters(rows, o.additionalParameters);
      break;
    }
    default:
      break;
  }
  return rows;
};

export const AuthDetails: React.FC<AuthDetailsProps> = ({
  auth,
  authModeLabels = {},
  inheritedFrom,
  emptyMessage,
  testId = 'auth-details'
}) => {
  if (!auth) {
    return emptyMessage ? <PropertyTable rows={[]} emptyMessage={emptyMessage} testId={testId} /> : null;
  }

  const rows: PropertyRow[] = [{ label: 'Mode', value: modeLabel(auth, authModeLabels), testId: 'mode' }];

  if (auth === 'inherit') {
    if (inheritedFrom) rows.push({ label: 'Inherited From', value: inheritedFrom, testId: 'inherited-from' });
  } else {
    rows.push(...buildAuthRows(auth));
  }

  return <PropertyTable rows={rows} testId={testId} />;
};

export default AuthDetails;

import { md5 } from 'js-md5';

export interface DigestChallenge {
  [key: string]: string | undefined;
  realm?: string;
  nonce?: string;
  qop?: string;
  opaque?: string;
  algorithm?: string;
}

export type DigestBuildFailure = 'malformed-challenge' | 'unsupported-algorithm' | 'unsupported-qop';

export type DigestAuthResult
  = | { ok: true; header: string }
    | { ok: false; reason: DigestBuildFailure };

export interface BuildDigestOptions {
  challenge: DigestChallenge;
  method: string;
  uri: string;
  username: string;
  password: string;
  cnonce?: string;
}

export interface DigestCredentials {
  username: string;
  password: string;
}

export const getDigestCredentials = (auth: Record<string, unknown> | undefined): DigestCredentials | null => {
  if (auth?.type !== 'digest' || typeof auth.username !== 'string' || auth.username === '') {
    return null;
  }
  return { username: auth.username, password: typeof auth.password === 'string' ? auth.password : '' };
};

export interface ParsedChallenge {
  scheme: string;
  params: DigestChallenge;
}

// A WWW-Authenticate value is a comma-separated list, but commas can also appear
// inside quoted values (realm="a, b" or qop="auth-int,auth"). A plain split(',')
// would cut those values apart, so this only splits on commas that sit outside quotes.
const splitOnUnquotedCommas = (input: string): string[] => {
  const parts: string[] = [];
  let current = '';
  let inQuotes = false;
  for (let i = 0; i < input.length; i += 1) {
    const ch = input[i];
    if (ch === '"') {
      inQuotes = !inQuotes;
      current += ch;
    } else if (ch === '\\' && inQuotes && i + 1 < input.length) {
      // Backslash escapes the next character (e.g. \" inside a quoted value), so
      // take both characters now and skip ahead — the quote must not end the string.
      current += ch + input[i + 1];
      i += 1;
    } else if (ch === ',' && !inQuotes) {
      parts.push(current);
      current = '';
    } else {
      current += ch;
    }
  }
  parts.push(current);
  return parts.map((part) => part.trim()).filter(Boolean);
};

const unquote = (value: string): string => {
  const trimmed = value.trim();
  if (trimmed.startsWith('"') && trimmed.endsWith('"') && trimmed.length >= 2) {
    return trimmed.slice(1, -1).replace(/\\(.)/g, '$1');
  }
  return trimmed;
};

const SCHEME_PREFIX = /^([A-Za-z][A-Za-z0-9._~+/-]*)\s+(.*)$/;

export const parseChallenges = (header: string): ParsedChallenge[] => {
  const challenges: ParsedChallenge[] = [];
  let current: ParsedChallenge | null = null;

  const addParam = (target: ParsedChallenge | null, pair: string): void => {
    const idx = pair.indexOf('=');
    if (idx === -1 || target === null) return;
    const key = pair.substring(0, idx).trim().toLowerCase();
    if (key) target.params[key] = unquote(pair.substring(idx + 1));
  };

  splitOnUnquotedCommas(header).forEach((part) => {
    const prefixed = SCHEME_PREFIX.exec(part);
    if (prefixed && !prefixed[2].startsWith('=') && prefixed[2].includes('=')) {
      current = { scheme: prefixed[1].toLowerCase(), params: {} };
      challenges.push(current);
      addParam(current, prefixed[2]);
    } else if (!part.includes('=')) {
      current = { scheme: part.toLowerCase(), params: {} };
      challenges.push(current);
    } else {
      addParam(current, part);
    }
  });

  return challenges;
};

const isSupportedAlgorithm = (challenge: DigestChallenge): boolean =>
  !challenge.algorithm || challenge.algorithm.toUpperCase() === 'MD5';

export const findDigestChallenge = (header: string): DigestChallenge | null => {
  const digests = parseChallenges(header).filter((challenge) => challenge.scheme === 'digest');
  if (digests.length === 0) return null;
  const supported = digests.find((challenge) => isSupportedAlgorithm(challenge.params));
  return (supported ?? digests[0]).params;
};

const hasQopAuth = (qop: string | undefined): boolean =>
  Boolean(qop && qop.split(',').map((q) => q.trim().toLowerCase()).includes('auth'));

const randomCnonce = (): string => {
  const bytes = new Uint8Array(24);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
};

const quote = (value: string): string => `"${value.replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;

const hasControlChars = (value: string): boolean =>
  Array.from(value).some((ch) => {
    const code = ch.codePointAt(0) ?? 0;
    return code < 0x20 || code === 0x7f;
  });

export const buildDigestAuthorization = (options: BuildDigestOptions): DigestAuthResult => {
  const { challenge, method, uri, username, password, cnonce = randomCnonce() } = options;

  if (!challenge.realm || !challenge.nonce) {
    return { ok: false, reason: 'malformed-challenge' };
  }

  if ([challenge.realm, challenge.nonce, challenge.opaque ?? ''].some(hasControlChars)) {
    return { ok: false, reason: 'malformed-challenge' };
  }

  if (challenge.algorithm && challenge.algorithm.toUpperCase() !== 'MD5') {
    return { ok: false, reason: 'unsupported-algorithm' };
  }

  const useQop = hasQopAuth(challenge.qop);
  if (challenge.qop && !useQop) {
    return { ok: false, reason: 'unsupported-qop' };
  }

  const nc = '00000001';
  const ha1 = md5(`${username}:${challenge.realm}:${password}`);
  const ha2 = md5(`${method.toUpperCase()}:${uri}`);
  const response = useQop
    ? md5(`${ha1}:${challenge.nonce}:${nc}:${cnonce}:auth:${ha2}`)
    : md5(`${ha1}:${challenge.nonce}:${ha2}`);

  const fields = [
    `username=${quote(username)}`,
    `realm=${quote(challenge.realm)}`,
    `nonce=${quote(challenge.nonce)}`,
    `uri=${quote(uri)}`,
    `response=${quote(response)}`
  ];

  if (useQop) {
    fields.push('qop=auth', 'algorithm=MD5', `nc=${nc}`, `cnonce=${quote(cnonce)}`);
  }

  if (challenge.opaque) {
    fields.push(`opaque=${quote(challenge.opaque)}`);
  }

  return { ok: true, header: `Digest ${fields.join(', ')}` };
};

import type { Locator } from '@playwright/test';
import { BaseComponent } from '../base.component';

// The Auth tab inside the playground request pane: the auth-mode dropdown, its options,
// and the notice shown when a request inherits its auth. Open the tab via
// playground.selectTab('auth').
export class RequestAuthComponent extends BaseComponent {
  readonly modeSelect = this.page.getByTestId('auth-mode-select');
  readonly inheritNotice = this.page.getByTestId('auth-inherit-notice');
  readonly options = this.page.getByTestId(/^auth-mode-select-(?!dropdown$)/);

  option(value: string): Locator {
    return this.page.getByTestId(`auth-mode-select-${value}`);
  }

  field(name: string): Locator {
    return this.page.getByTestId(`auth-${name}`);
  }

  async open(): Promise<void> {
    await this.modeSelect.click();
  }

  async selectMode(value: string): Promise<void> {
    await this.modeSelect.click();
    await this.option(value).click();
  }
}

